// This is based on the example code found from:
// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Math/floor
// Example code on MDN is public domain or CC0 (your preference) or MIT depending when the
// example code was added:
// https://developer.mozilla.org/en-US/docs/MDN/About
const round10 = (value, exp) => {
    // If the exp is undefined or zero...
    if (typeof exp === "undefined" || +exp === 0) {
        return Math.round(value);
    }
    let val = +value;
    exp = +exp;
    // If the value is not a number or the exp is not an integer...
    if (isNaN(val) || !(typeof exp === "number" && exp % 1 === 0)) {
        return NaN;
    }
    // Shift
    let vals = val.toString().split("e");
    val = Math.round(+(vals[0] + "e" + (vals[1] ? +vals[1] - exp : -exp)));
    // Shift back
    vals = val.toString().split("e");
    return +(vals[0] + "e" + (vals[1] ? +vals[1] + exp : exp));
};

